import hashlib,json
from pathlib import Path
H=Path(__file__).resolve().parent;B=H.parent
for n in ('controls','evaluation'):(H/n).mkdir(parents=True,exist_ok=True)
def write(p,x):p.write_text(json.dumps(x,indent=2)+'\n',encoding='utf8')
source='1-chloro-2-nitrobenzene';candidate='Clc1ccccc1[N+](=O)[O-]'
def case(i,name,s,aliases,op,dim,why):return {'id':i,'source_name':name,'candidate':s,'aliases':aliases,'expected_operation':op,'expected_dimension':dim,'justification':why,'review':'CHEMICAL_REVIEW_PENDING','references':['https://iupac.qmul.ac.uk/BlueBook/P1.html#P-13.1','https://iupac.qmul.ac.uk/BlueBook/P7.html','https://iupac.qmul.ac.uk/BlueBook/P5.html']}
positive=[case('P1',source,candidate,[],'SUPPORTED','SUPPORTED','Whole NSC-002 source and candidate context comprises benzene, halo and N-attached nitro only.'),case('P2',source,'ClC1=CC=CC=C1[N+]([O-])=O',[source.upper()],'SUPPORTED','SUPPORTED','Equivalent nitro oxygen ordering and Kekule depiction; all aliases independently in scope.')]
unknown=[case('U1','nitrobenzoic acid','O=C(O)c1ccc([N+](=O)[O-])cc1',[],'UNKNOWN','UNKNOWN','Additional acid site and source locants are outside supported grammar.'),case('U2','nitroaniline','Nc1ccc([N+](=O)[O-])cc1',[],'UNKNOWN','UNKNOWN','Uninterpreted amino protonation sites and source scope.'),case('U3','glycine','[NH3+]CC(=O)[O-]',[],'UNKNOWN','UNKNOWN','Net neutrality does not establish proton locations.'),case('U4',source,candidate,['chloro nitrobenzene'],'SUPPORTED','UNKNOWN','Preferred operation supported; alias specificity is not established.'),case('U5',source,candidate+'.Cl',[],'UNKNOWN','UNKNOWN','Extra component outside v1.'),case('U6',source,'Clc1ccccc1N=O',[],'UNKNOWN','UNKNOWN','Nitroso is not supported neutral nitro.'),case('U7',source,'Clc1ccccc1ON=O',[],'UNKNOWN','UNKNOWN','Nitrite ester attaches via oxygen.'),case('U8',source,'Clc1ccccc1O[N+](=O)[O-]',[],'UNKNOWN','UNKNOWN','Nitrate ester differs from N-attached nitro.'),case('U9',source,candidate,['1-chloro-3-nitrobenzene'],'SUPPORTED','UNKNOWN','Specific incompatible alias must remain an independent source conflict.')]
held=[case('H1','1-bromo-3-nitrobenzene','Brc1cccc([N+](=O)[O-])c1',[],'SUPPORTED','SUPPORTED','Public frozen different substitution pattern.'),case('H2','1-bromo-3-nitrobenzene','Brc1cccc([N+](=O)[O-])c1',['bromonitrobenzene'],'SUPPORTED','UNKNOWN','Unclosed alias scope.'),case('H3','1-bromo-3-nitrobenzene','Brc1cccc([N+](=O)[O-])c1.[Na+]',[],'UNKNOWN','UNKNOWN','Unsupported charged extra component.')]
pairs=[{'id':'C1','a':'CCO','b':'COC','expected':'UNKNOWN','why':'Constitution differs; no meaningful protonation correspondence.'},{'id':'C2','a':'O=C(O)c1ccccc1','b':'O=C([O-])c1ccccc1','expected':'DIFFERENT','why':'Benzoic acid and benzoate differ by proton and net charge.'},{'id':'C3','a':'Nc1ccc([N+](=O)[O-])cc1','b':'[NH3+]c1ccc([N+](=O)[O-])cc1','expected':'DIFFERENT','why':'Nitro does not mask amine protonation.'},{'id':'C4','a':'O=C(O)c1ccc([N+](=O)[O-])cc1','b':'O=C([O-])c1ccc([N+](=O)[O-])cc1','expected':'DIFFERENT','why':'Nitro does not mask carboxyl protonation.'},{'id':'C5','a':'NCC(=O)O','b':'[NH3+]CC(=O)[O-]','expected':'DIFFERENT','why':'Same net charge and total H, different proton/charge locations; source glycine meaning is unassessed.'},{'id':'C6','a':candidate,'b':'[O-][N+](=O)c1ccccc1Cl','expected':'EQUIVALENT','why':'Equivalent nitro representation.'},{'id':'C7','a':'c1ccccc1','b':'C1CCCCC1','expected':'UNKNOWN','why':'Different hydrogenation is not a pure protonation transformation.'}]
write(H/'controls/positive_controls.json',positive);write(H/'controls/unknown_controls.json',unknown);write(H/'controls/heldout_controls.json',held);write(H/'controls/contradiction_controls.json',{'layer':'Structural attribution, not source semantics','cases':pairs,'review':'CHEMICAL_REVIEW_PENDING'})
spec={'version':'1.0','source_scope':'Unchanged full NSC-002 grammar with at least one nitro and complete candidate correspondence. Every provided alias must be independently in the same closed grammar and compatible; otherwise dimension UNKNOWN.','site_closure':'Only benzene, supported halo and neutral N-attached nitro sites; all outside context abstains.','dimension_negative_boundary':'No new general protonation-source grammar. Structurally incompatible outside-envelope nitro candidates return UNKNOWN; valid protonation contradictions are tested separately in attribution comparator.','review':'CHEMICAL_REVIEW_PENDING'}
write(H/'controls/chemical_scope.json',spec)
files=list((H/'controls').glob('*.json'));write(H/'controls/benchmark_freeze.json',{'stage':'PRE_IMPLEMENTATION','sha256':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in files},'holdout':'PUBLIC_FROZEN_NOT_BLINDED'})
files=[B/n for n in ('resolver.py','source_form.py','form_characterizer.py','identity_comparator.py','providers.py','provider_capabilities.py','evidence_model.py','comptox.py','schema.sql','output/registry.sqlite','fresh_blinded_evaluation/run/candidates.sqlite','deterministic_value_analysis/deterministic_interpretation_cases.json','fresh_blinded_evaluation/fresh_sample.json')]
for d in ('nsc_architecture_experiment/NSC-001','nsc_architecture_experiment/shared','nsc_architecture_experiment/architecture_B','nsc002_experiment/NSC-002','nsc002_experiment/architecture_B'):
 files += [p for p in (B/d).rglob('*') if p.is_file() and '__pycache__' not in str(p)]
write(H/'evaluation/pre_implementation_hashes.json',{'files':{str(p.relative_to(B)).replace('\\','/'):hashlib.sha256(p.read_bytes()).hexdigest() for p in files}})
print('Controls and bounded scope frozen before implementation.')
